using System.Reflection;

var asm = Assembly.LoadFrom(
    Path.Combine(
        Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),
        ".nuget/packages/microsoft.agents.ai/1.13.0/lib/net10.0/Microsoft.Agents.AI.dll"));

// Look at ChatClientAgentOptions, ChatClientAgentRunOptions, LoopAgentOptions, AIAgentBuilder
foreach (var typeName in new[] { "ChatClientAgentOptions", "ChatClientAgentRunOptions", "LoopAgentOptions", "AIAgentBuilder", "AIAgentExtensions", "ChatClientAgentSession" })
{
    var t = asm.GetExportedTypes().FirstOrDefault(t => t.Name == typeName);
    if (t == null) { Console.WriteLine($"[NOT FOUND] {typeName}"); continue; }
    Console.WriteLine($"\n[TYPE] {t.FullName} (base: {t.BaseType?.Name})");
    foreach (var c in t.GetConstructors(BindingFlags.Public | BindingFlags.Instance))
        Console.WriteLine($"  CTOR: ({string.Join(", ", c.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"))})");
    foreach (var p in t.GetProperties(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly))
        Console.WriteLine($"  PROP: {p.PropertyType.Name} {p.Name} {(p.CanWrite ? "get;set;" : "get;")}");
    foreach (var m in t.GetMethods(BindingFlags.Public | BindingFlags.Static | BindingFlags.Instance | BindingFlags.DeclaredOnly).Where(m => !m.IsSpecialName))
        Console.WriteLine($"  METHOD: {(m.IsStatic ? "static " : "")}{m.ReturnType.Name} {m.Name}({string.Join(", ", m.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"))})");
}
CSEOF
