using System.ComponentModel;
using System.Net;
using System.Text;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;

// ─── Configuration ───────────────────────────────────────────────────────────
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// ─── Tools ───────────────────────────────────────────────────────────────────
var notebook = new ResearchNotebook();
var tools = new AITool[]
{
    AIFunctionFactory.Create(WebSearchTool.SearchAsync),
    AIFunctionFactory.Create(WebSearchTool.FetchPageAsync),
    AIFunctionFactory.Create(notebook.AddNote),
    AIFunctionFactory.Create(notebook.GetNotes),
};

// ─── Build the agent ─────────────────────────────────────────────────────────
var chatClient = new OpenAI.OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research assistant. When given a topic:
        1. Search the web for relevant information using different search queries.
        2. Fetch promising pages to read their content.
        3. Take notes on the key findings using the note-taking tool.
        4. After gathering enough information, compile a well-organized summary from your notes.

        Be thorough — use multiple search queries to cover different angles of the topic.
        Always save important findings as notes before writing the final summary.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and summarizing findings.",
    tools: tools);

var loopAgent = new LoopAgent(
    agent,
    new CompletionMarkerLoopEvaluator(),
    new LoopAgentOptions { MaxIterations = 15 });

// ─── Run ─────────────────────────────────────────────────────────────────────
Console.ForegroundColor = ConsoleColor.Cyan;
Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       🔍  Research Agent  🔍        ║");
Console.WriteLine("╠══════════════════════════════════════╣");
Console.WriteLine("║  Enter a topic to research.         ║");
Console.WriteLine("║  Type 'quit' to exit.               ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.ResetColor();

while (true)
{
    Console.WriteLine();
    Console.ForegroundColor = ConsoleColor.Green;
    Console.Write("Topic> ");
    Console.ResetColor();

    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    notebook.Clear();
    Console.ForegroundColor = ConsoleColor.Yellow;
    Console.WriteLine($"\nResearching: {topic}\n");
    Console.ResetColor();

    try
    {
        var session = await loopAgent.CreateSessionAsync();
        var response = await loopAgent.RunAsync(
            $"Research the following topic and provide a comprehensive summary: {topic}",
            session);

        Console.ForegroundColor = ConsoleColor.White;
        Console.WriteLine(response.Text);
        Console.ResetColor();

        if (notebook.Count > 0)
        {
            Console.ForegroundColor = ConsoleColor.DarkGray;
            Console.WriteLine($"\n[{notebook.Count} note(s) taken during research]");
            Console.ResetColor();
        }
    }
    catch (Exception ex)
    {
        Console.ForegroundColor = ConsoleColor.Red;
        Console.Error.WriteLine($"Error: {ex.Message}");
        Console.ResetColor();
    }
}

// ─── Web Search Tool ─────────────────────────────────────────────────────────
static class WebSearchTool
{
    private static readonly HttpClient HttpClient = new()
    {
        Timeout = TimeSpan.FromSeconds(15),
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" },
            { "Accept", "text/html,application/xhtml+xml,application/json" },
        },
    };

