+
+        var snippetTag = "class=\"result__snippet";
+        var titleTag = "class=\"result__a\"";
+        var idx = 0;
+
+        while (resultCount < 8 && idx < html.Length)
+        {
+            var titleIdx = html.IndexOf(titleTag, idx, StringComparison.Ordinal);
+            if (titleIdx < 0) break;
+
+            var hrefIdx = html.LastIndexOf("href=\"", titleIdx, Math.Min(titleIdx, 200), StringComparison.Ordinal);
+            var href = "";
+            if (hrefIdx >= 0)
+            {
+                hrefIdx += 6;
+                var hrefEnd = html.IndexOf('"', hrefIdx);
+                if (hrefEnd > hrefIdx)
+                    href = WebUtility.HtmlDecode(html[hrefIdx..hrefEnd]);
+            }
+
+            var titleContentStart = html.IndexOf('>', titleIdx) + 1;
+            var titleContentEnd = html.IndexOf("</a>", titleContentStart, StringComparison.Ordinal);
+            var title = titleContentEnd > titleContentStart
+                ? StripHtmlTags(html[titleContentStart..titleContentEnd]).Trim()
+                : "(no title)";
+
+            var snippet = "";
+            var snippetIdx = html.IndexOf(snippetTag, titleIdx, StringComparison.Ordinal);
+            if (snippetIdx >= 0 && snippetIdx - titleIdx < 2000)
+            {
+                var snippetStart = html.IndexOf('>', snippetIdx) + 1;
+                var snippetEnd = html.IndexOf("</a>", snippetStart, StringComparison.Ordinal);
+                if (snippetEnd < 0) snippetEnd = html.IndexOf("</span>", snippetStart, StringComparison.Ordinal);
+                if (snippetEnd > snippetStart)
+                    snippet = StripHtmlTags(html[snippetStart..snippetEnd]).Trim();
+            }
+
+            resultCount++;
+            results.AppendLine($"{resultCount}. {title}");
+            if (!string.IsNullOrEmpty(href))
+                results.AppendLine($"   URL: {href}");
+            if (!string.IsNullOrEmpty(snippet))
+                results.AppendLine($"   {snippet}");
+            results.AppendLine();
+
+            idx = titleIdx + 1;
+        }
+
+        return resultCount > 0
+            ? results.ToString()
+            : "No results found.";
+    }
+
+    private static string StripHtmlTags(string html)
+    {
+        var sb = new StringBuilder(html.Length);
+        var inTag = false;
+
+        foreach (var ch in html)
+        {
+            if (ch == '<') { inTag = true; continue; }
+            if (ch == '>') { inTag = false; continue; }
+            if (!inTag) sb.Append(ch);
+        }
+
+        var text = WebUtility.HtmlDecode(sb.ToString());
+        // Collapse whitespace
+        return System.Text.RegularExpressions.Regex.Replace(text, @"\s+", " ").Trim();
+    }
+}
+
+// ─── Note-Taking Tool ───────────────────────────────────────────────────────
+class ResearchNotebook
+{
+    private readonly List<(string Category, string Content)> _notes = [];
+
+    public int Count => _notes.Count;
+
+    [Description("Save a research note with a category label. Use this to record important findings.")]
+    public string AddNote(
+        [Description("Category for the note (e.g. 'key-fact', 'statistic', 'quote', 'source')")] string category,
+        [Description("The content of the note")] string content)
+    {
+        _notes.Add((category, content));
+
+        Console.ForegroundColor = ConsoleColor.DarkYellow;
+        Console.WriteLine($"  📝 Note [{category}]: {(content.Length > 80 ? content[..80] + "..." : content)}");
+        Console.ResetColor();
+
+        return $"Note saved. You now have {_notes.Count} note(s).";
+    }
+
+    [Description("Retrieve all saved research notes, organized by category.")]
+    public string GetNotes()
+    {
+        if (_notes.Count == 0)
+            return "No notes saved yet.";
+
+        var sb = new StringBuilder();
+        foreach (var group in _notes.GroupBy(n => n.Category))
+        {
+            sb.AppendLine($"## {group.Key}");
+            foreach (var (_, content) in group)
+                sb.AppendLine($"- {content}");
+            sb.AppendLine();
+        }
+
+        return sb.ToString();
+    }
+
+    public void Clear() => _notes.Clear();
+}

